```python
def has_cycle_undirected(n, graph):
    visited = set()

    def dfs(node, parent):
        visited.add(node)
        for neighbor in graph[node]:
            if neighbor not in visited:
                if dfs(neighbor, node):
                    return True
            elif neighbor != parent:
                return True          # visited, and not where we came from
        return False

    for node in range(n):
        if node not in visited:
            if dfs(node, -1):
                return True
    return False
```

The outer loop is the same connected-components pattern from earlier — a disconnected graph might have a cycle in a piece the first traversal never reaches.

```python
WHITE, GRAY, BLACK = 0, 1, 2

def has_cycle_directed(n, graph):
    color = [WHITE] * n

    def dfs(node):
        color[node] = GRAY
        for neighbor in graph[node]:
            if color[neighbor] == GRAY:
                return True             # back edge into the current path
            if color[neighbor] == WHITE and dfs(neighbor):
                return True
        color[node] = BLACK             # fully done with this node
        return False

    for node in range(n):
        if color[node] == WHITE:
            if dfs(node):
                return True
    return False
```

The recursion-stack marker (`GRAY`) is the entire fix over plain "visited": it's set on entry and cleared to `BLACK` only on exit, so it precisely tracks "currently in progress" rather than "ever visited."
